scwin.vScrenID = "ULDSTF05937.xml";
scwin.clickIsuCd;
scwin.clickIsuKorAbbrv;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/*function fn_setElwInstNm_1() {
	dts_ELW_INST_NM_1.DataID = "/CodeAction.do?method=listWrntCd&For=R";
	dts_ELW_INST_NM_1.Reset();
}*/

scwin.fn_setLpNm_3 = function() {
    dts_LP_NM_3.DataID = "/CodeAction.do?method=listLeadCom&For=R";
    dts_LP_NM_3.Reset();
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=ELW_LP_NOW_ALL_HD_LIST_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwallhold.select.nowallhdlist" + "&{P}param01=" + $c.stf.getObjectValue(edt_NOW_DD) + "&{P}param02=" + $c.stf.getObjectValue(edt_NOW_DD);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_NOW_ALL_HD_LIST.DataID = encodeURI(url);
    dts_NOW_ALL_HD_LIST.reset();
    $c.cm.ShowWin(grd_NOW_ALL_HD_LIST);
};
scwin.fn_setTaskDd_3 = function() {
    var url = "/ELWAllHoldAction.do?method=calendarSearch&inputMessageId=ELW_LP_ALL_HD_TASK_DD_GET_OUT";
    dts_NOW_DD.DataID = encodeURI(url);
    dts_NOW_DD.reset();
};
scwin.fn_OpenDetail_3 = async function(row) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.clickIsuCd = dts_NOW_ALL_HD_LIST.getCellData(row, "ISU_CD");
        scwin.clickIsuKorAbbrv = dts_NOW_ALL_HD_LIST.getCellData(row, "ISU_NM");
        await $c.frame.CreateDialogFrame("ULDSTF35503", "/lstmgt/ULDSTF35503.gfm", "개별종목보유수량조회", 100, 100, 905, 570 + 35, "");
    }
};
scwin.fn_ExcelDown = function() {
    $c.data.downloadGridViewExcel(grd_NOW_ALL_HD_LIST, "당일전부보유리스트", "", "8");
};
scwin.fn_getBzProcsNo = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=ELW_LP_NOW_ALL_HD_LIST_BZNO_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwallhold.select.bzprocsno" + "&{P}param01=" + $c.stf.getObjectValue(edt_NOW_DD);
    dts_BzProcsNo.DataID = encodeURI(url);
    dts_BzProcsNo.reset();
};


//안내문 작성  - 당일 전부보유목록 
scwin.fn_dscl = async function() {
    var vBzProcsNo = "";

    //2010.07.23 업무처리번호 유무 - 정정공시를 위해 
    scwin.fn_getBzProcsNo();
    vBzProcsNo = dts_BzProcsNo.getCellData(1, "BZ_PROCS_NO");
    if (vBzProcsNo == "") vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_setLpNm_3();
    //dts_DISC.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    var cont = 1;
    var overCheck = false;
    var tempK = 0;
    for (var i = 1; i <= dts_LP_NM_3.getTotalRow(); i++) {
        var pLpMbtNm = "";
        var pIsuNm = "";
        var pCheck = false;
        var pcount = 0;
        var pLenStr = 0;
        var cnt = 1;
        for (var k = 1; k <= dts_NOW_ALL_HD_LIST.getTotalRow(); k++) {
            if (overCheck) {
                k = tempK;
                overCheck = false;
            }
            if (dts_LP_NM_3.getCellData(i, "VALUE") == dts_NOW_ALL_HD_LIST.getCellData(k, "LP_MBR_NO")) {
                //pIsuNm =  pIsuNm + (pIsuNm == "" ? "" : ", ")  + dts_NOW_ALL_HD_LIST.NameString(k, "ISU_NM");
                pLpMbtNm = dts_LP_NM_3.getCellData(i, "TEXT");
                if (pcount > 0) {
                    pIsuNm = pIsuNm + ",";
                }
                if (pcount % 4 == 0 && pcount != 0) pIsuNm = pIsuNm + "\n" + dts_NOW_ALL_HD_LIST.getCellData(k, "ISU_NM");

                else pIsuNm = pIsuNm + dts_NOW_ALL_HD_LIST.getCellData(k, "ISU_NM");
                pcount++;
                pCheck = true;
                if (pcount > 239) {
                    i--;
                    tempK = k + 1;
                    k = dts_NOW_ALL_HD_LIST.getTotalRow() + 1;
                    overCheck = true;
                    pIsuNm = pIsuNm + ","; //SrM-000191426 ELW 상장공시시스템 개발 변경 추가 요구 사항

                }

            }
        }
        if (pCheck) {
            dts_DISC.insertRow();
            dts_DISC.setCellData(cont, "LP_MBR_NM", pLpMbtNm);
            dts_DISC.setCellData(cont, "ISU_NM", pIsuNm);
            cont++;
        }
    }
    scwin.fn_GetPar = function(arr, param_dts_NOW_ALL_HD_LIST, param_dts_NOW_DD, param_dts_DISC) {
        arr[0] = "99879";
        arr[1] = vBzProcsNo;
        arr[2] = '99999'; //거래소코드
        arr[3] = '1'; //시장구분

        $c.stf.CopyDataSet(dts_NOW_ALL_HD_LIST, param_dts_NOW_ALL_HD_LIST);
        $c.stf.CopyDataSet(dts_NOW_DD, param_dts_NOW_DD);
        $c.stf.CopyDataSet(dts_DISC, param_dts_DISC);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.btn_Search_3_onclick = function() {
    scwin.fn_list_sync();
};
scwin.img_Excel_3_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.img_NOW_DD_onclick = function() {
    popUpCalendar2(edt_NOW_DD);
};
scwin.dts_NOW_ALL_HD_LIST_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
    //alert_error(dts_NOW_ALL_HD_LIST);

};
scwin.dts_NOW_DD_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
    //alert_error(dts_NOW_DD);

};
scwin.dts_NOW_ALL_HD_LIST_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_3);
    $c.cm.CloseWin(rowcount, grd_NOW_ALL_HD_LIST);
};
scwin.grd_NOW_ALL_HD_LIST_OnDblClick = function(row, colid) {
    if (colid == "ISU_NM") {
        scwin.fn_OpenDetail_3(row);
    }
};
scwin.btn_Dscl_onclick = function() {
    scwin.fn_dscl();
};
scwin.btn_Close_3_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_setTaskDd_3();
    $c.cm.PanelToGroupBox(panel_Top_3);
    scwin.fn_list_sync();
};
